from pathlib import Path
from datetime import datetime,timezone
import subprocess, json, shlex, hashlib, re, sys, time
p=Path(__file__).resolve().parent
root=p.parent.parent
remote='/tmp/afdo_probe-tv13-pmu-20261118'
sdb=['sdb','-s','192.168.108.13:26101']
env=f'export LC_ALL=C HOME={remote} TMPDIR={remote} PERF_BUILDID_DIR={remote}/buildid LD_LIBRARY_PATH={remote}; cd {remote} || exit 1; '
gate=(p/'gate.sh').read_text()
def utc(): return datetime.now(timezone.utc).isoformat()
def run(label,args,timeout=30,shown=True):
    start=utc()
    proc=subprocess.run(sdb+args,capture_output=True,timeout=timeout)
    for k in ('stdout','stderr'):
        (p/f'{label}.{k}').write_bytes(getattr(proc,k))
    (p/f'{label}.json').write_text(json.dumps(dict(argv=sdb+args,start=start,end=utc(),rc=proc.returncode),indent=2)+'\n')
    if shown:
        print(label,proc.returncode,proc.stdout.decode(errors='replace')[:3500],proc.stderr.decode(errors='replace')[:1500],flush=True)
    return proc
def shell(label,cmd,timeout=30,shown=True):
    script=f'{cmd}\nrc=$?; printf "\\n__TV_RC__=%s\\n" "$rc"; exit "$rc"'
    proc=run(label,['shell',script],timeout,shown)
    match=re.search(rb'^__TV_RC__=(\d+)\s*$',proc.stdout,re.M)
    if proc.returncode or not match or int(match[1]):
        raise RuntimeError(f'{label}: host rc {proc.returncode}, board rc {match[1].decode() if match else "missing"}')
    return proc.stdout
def cleanup():
    shell('cleanup-tmp',f'rm -rf -- {remote} && test ! -e {remote} && test ! -L {remote} && echo verified-absent')
def check(label):
    out=shell(label,gate+'\n',shown=False).decode()
    print(label, out.splitlines()[:4],flush=True)
    established=re.findall(r'sdb-established (\d+)',out)
    if len(established)!=2 or sum(map(int,established))!=1:raise RuntimeError('SDB connection count changed or unknown')
    for line in out.splitlines():
        words=line.split()
        if len(words)>=5 and words[0].isdigit() and re.search(r'^(?:perf(?:$|[-_])|gdb(?:server)?$|stress(?:[-_]|$)|sysbench$|fio$|afdo_|branch-[01]$)',words[-1],re.I):
            raise RuntimeError(f'Potential concurrent test process: {line}')
    first=next(line for line in out.splitlines() if re.match(r'^\d+\.\d+ \d+\.\d+ ',line))
    top=out.splitlines()[3:18]
    for line in top:
        w=line.split()
        if len(w)>=6 and w[0].isdigit() and float(w[3])>=5.0 and w[-1] not in ('sh','ps','awk','head'):
            raise RuntimeError(f'Unexpected high CPU process: {line}')
    if float(first.split()[0])>31:raise RuntimeError(f'Load rose from pre-deployment baseline: {first}')
    return out
def deploy():
    check('gate-deploy')
    (p/'cleanup-journal.json').write_text(json.dumps({'path':remote,'phase':'registered-before-create','utc':utc()},indent=2)+'\n')
    own=False
    try:
        try:
            shell('mkdir',f'umask 077; mkdir -- {remote}')
            own=True
        except Exception:
            raise
        sources={
         'perf':root/'temp/rpms/perf-extract/usr/bin/perf',
         'libLLVM.so.22.1':root/'temp/rpms/llvm-extract/usr/lib/libLLVM.so.22.1',
         'libxml2.so.16':p/'xml/usr/lib/libxml2.so.16.1.1',
         'branch-0':p/'branch-0','branch-1':p/'branch-1'}
        sha={n:hashlib.sha256(f.read_bytes()).hexdigest() for n,f in sources.items()}
        (p/'deployment.json').write_text(json.dumps({n:dict(sha256=sha[n],source=str(f.relative_to(root)),size=f.stat().st_size) for n,f in sources.items()},indent=2)+'\n')
        for n,f in sources.items():
            r=run('push-'+n,['push',str(f),remote+'/'+n],90)
            if r.returncode:raise RuntimeError('push failed '+n)
        wanted=''.join(f'{sha[n]}  {n}\n' for n in sources)
        shell('deploy-verify',env+'printf %s '+shlex.quote(wanted)+' | sha256sum -c - && chmod 755 perf branch-0 branch-1')
        shell('ldd-perf',env+'/lib/ld-linux.so.3 --list ./perf')
        shell('perf-version',env+'./perf --version')
        shell('perf-list-hw',env+'./perf list hw')
        shell('perf-list-raw',env+'./perf list raw')
        check('gate-after-deploy')
    except BaseException:
        if own:cleanup()
        raise
if __name__=='__main__':
    {'deploy':deploy,'cleanup':cleanup}[sys.argv[1]]()

